package com.smartgrading.backend.controller;
import com.smartgrading.backend.dto.*; import com.smartgrading.backend.service.AssignmentService; import jakarta.validation.Valid; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/assignments") public class AssignmentController { private final AssignmentService service; public AssignmentController(AssignmentService s){service=s;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public AssignmentResponse create(@Valid @RequestBody AssignmentRequest r){return service.create(r);} @GetMapping public List<AssignmentResponse> all(){return service.all();} @GetMapping("/{id}") public AssignmentResponse get(@PathVariable Integer id){return service.get(id);} @PutMapping("/{id}") public AssignmentResponse update(@PathVariable Integer id,@Valid @RequestBody AssignmentRequest r){return service.update(id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Integer id){service.delete(id);} @PostMapping("/{id}/publish") public AssignmentResponse publish(@PathVariable Integer id){return service.publish(id);} @PostMapping("/{id}/close") public AssignmentResponse close(@PathVariable Integer id){return service.close(id);} }
